126	/// Build the one-line JSON object printed by `prove`: integer tree_size and
127	/// leaf_index, the lowercase-hex root, and the audit path as a JSON array of
128	/// lowercase-hex hashes ordered leaf to root.
129	fn proof_json(tree_size: u64, leaf_index: u64, root: &[u8; 32], audit_path: &[[u8; 32]]) -> String {
130	    let mut out = String::new();
131	    out.push_str("{\"tree_size\":");
132	    out.push_str(&tree_size.to_string());
133	    out.push_str(",\"leaf_index\":");
134	    out.push_str(&leaf_index.to_string());
135	    out.push_str(",\"root\":\"");
136	    out.push_str(&hex(root));
137	    out.push_str("\",\"audit_path\":[");
138	    for (i, node) in audit_path.iter().enumerate() {
139	        if i > 0 {
140	            out.push(',');
141	        }
142	        out.push('"');
143	        out.push_str(&hex(node));
144	        out.push('"');
145	    }
146	    out.push_str("]}");
147	    out
148	}
