339	#[cfg(test)]
340	mod tests {
341	    use super::*;
342	
343	    fn hex_of(d: &[u8; 32]) -> String {
344	        hex(d)
345	    }
346	
347	    /// Verify an RFC 6962 inclusion proof with the RFC's recursive verifier:
348	    /// it re-derives the combination order from the tree geometry (k =
349	    /// largest power of two below the current subtree size) while consuming
350	    /// exactly the supplied sibling hashes. A wrong length, order or hash
351	    /// fails; the root computed here must equal the tree root.
352	    fn verify_proof(leaf: &[u8], m: usize, n: usize, path: &[[u8; 32]]) -> [u8; 32] {
353	        assert!(m < n);
354	        fn sub(leaf: &[u8], m: usize, n: usize, path: &[[u8; 32]], pos: &mut usize) -> [u8; 32] {
355	            if n == 1 {
356	                return leaf_hash(leaf);
357	            }
358	            let k = 1usize << (usize::BITS - 1 - (n - 1).leading_zeros());
359	            if m < k {
360	                let left = sub(leaf, m, k, path, pos);
361	                assert!(*pos < path.len(), "proof too short");
362	                let right = path[*pos];
363	                *pos += 1;
364	                node_hash(&left, &right)
365	            } else {
366	                let right = sub(leaf, m - k, n - k, path, pos);
367	                assert!(*pos < path.len(), "proof too short");
368	                let left = path[*pos];
369	                *pos += 1;
370	                node_hash(&left, &right)
371	            }
372	        }
373	        let mut pos = 0;
374	        let root = sub(leaf, m, n, path, &mut pos);
375	        assert_eq!(pos, path.len(), "proof too long: {pos} consumed of {}", path.len());
376	        root
377	    }
