398	    #[test]
399	    fn record_splitting() {
400	        assert_eq!(split_records(b""), Vec::<&[u8]>::new());
401	        assert_eq!(split_records(b"\n"), vec![b"".as_slice()]);
402	        assert_eq!(split_records(b"a\nb"), vec![b"a".as_slice(), b"b".as_slice()]);
403	        assert_eq!(split_records(b"a\nb\n"), vec![b"a".as_slice(), b"b".as_slice()]);
404	        assert_eq!(split_records(b"a\n\n"), vec![b"a".as_slice(), b"".as_slice()]);
405	        assert_eq!(split_records(b"a\n\n\n"), vec![b"a".as_slice(), b"".as_slice(), b"".as_slice()]);
406	        // CR is content, not a separator.
407	        assert_eq!(split_records(b"a\r\nb\r\n"), vec![b"a\r".as_slice(), b"b\r".as_slice()]);
408	        // Non-UTF-8 bytes are fine.
409	        assert_eq!(split_records(b"\xff\xfe\n\x00"), vec![b"\xff\xfe".as_slice(), b"\x00".as_slice()]);
410	    }
