412	    #[test]
413	    fn mth_rfc6962() {
414	        // Empty tree: SHA-256 of empty input.
415	        assert_eq!(hex_of(&mth(&[])), hex_of(&sha256(b"")));
416	        // Single leaf: SHA-256(0x00 || leaf).
417	        let leaf = b"hello";
418	        let mut expect = vec![0x00];
419	        expect.extend_from_slice(leaf);
420	        assert_eq!(hex_of(&mth(&[leaf])), hex_of(&sha256(&expect)));
421	        // Two leaves: SHA-256(0x01 || L || R).
422	        let l = mth(&[b"a"]);
423	        let r = mth(&[b"b"]);
424	        let mut expect = vec![0x01];
425	        expect.extend_from_slice(&l);
426	        expect.extend_from_slice(&r);
427	        assert_eq!(hex_of(&mth(&[b"a", b"b"])), hex_of(&sha256(&expect)));
428	        // Three leaves: split k=2, right subtree is a single leaf.
429	        let left = mth(&[b"a", b"b"]);
430	        let right = mth(&[b"c"]);
431	        let mut expect = vec![0x01];
432	        expect.extend_from_slice(&left);
433	        expect.extend_from_slice(&right);
434	        assert_eq!(hex_of(&mth(&[b"a", b"b", b"c"])), hex_of(&sha256(&expect)));
435	    }
