1	//! End-to-end regression tests for `roottrace prove <file> <record-index>`.
2	//!
3	//! The expected JSON lines are FIXED vectors produced independently of
4	//! roottrace by `tests/reference/rfc6962_vectors.py`, which computes RFC 6962
5	//! section 2.1.1 audit paths two different ways (the recursive PATH
6	//! definition and a top-down descent whose sibling subtree hashes come from
7	//! the structurally separate stack fold), then re-verifies every path with a
8	//! recursive inclusion verifier over `hashlib.sha256`. The constants here are
9	//! copied from that generator and never derived from roottrace output.
10	//!
11	//! Besides pinning the exact bytes of the success output, these tests check:
12	//!   * `root` equals what `roottrace root` prints for the same file
13	//!   * identical content at two positions yields two different proofs
14	//!   * trailing-LF / no-trailing-LF files give byte-identical proofs
15	//!   * an empty file has no selectable record; index >= size exits 1
16	//!   * bad or missing/extra arguments exit 2 with a usage message
17	//!   * unreadable files exit 1 and write nothing to stdout
18	
19	mod common;
20	
21	use std::process::Command;
22	
23	use common::{join_lf, TempDir, TempFile};
24	
25	// --- Fixed file payloads (copied from the reference generator) --------------
26	
27	const PAYLOAD_B8: &[u8] =
28	    b"alpha\nbeta\n\ngamma\nalpha\ndelta\r\n\xff\xfe\x00binary\nepsilon\n";
29	const PAYLOAD_B9: &[u8] =
30	    b"alpha\nbeta\n\ngamma\nalpha\ndelta\r\n\xff\xfe\x00binary\nepsilon\nzeta\x01tail\n";
31	const PAYLOAD_ONE_LF: &[u8] = b"\n";
32	const PAYLOAD_EMPTY: &[u8] = b"";
33	
