99	/// Run `roottrace prove <file> <index>` and return the completed output.
100	fn run_prove(path: &std::path::Path, index: &str) -> std::process::Output {
101	    Command::new(common::bin())
102	        .arg("prove")
103	        .arg(path)
104	        .arg(index)
105	        .output()
106	        .expect("failed to execute roottrace binary")
107	}
