145	/// Extract the 64-hex `root` field value from a prove JSON line.
146	fn root_field(json_line: &str) -> &str {
147	    let key = "\"root\":\"";
148	    let start = json_line.find(key).expect("root field present") + key.len();
149	    &json_line[start..start + 64]
150	}
