152	#[test]
153	fn fixed_proof_vectors_match_reference_constants() {
154	    assert_proof_success(
155	        "B9 m=0 (first record, uneven 9-record tree)",
156	        PAYLOAD_B9,
157	        "0",
158	        &expected_json(9, 0, ROOT_B9, PATH_B9_M0),
159	    );
