193	fn proof_root_equals_root_command_for_the_same_file() {
194	    for (desc, bytes, index) in [
195	        ("B9/0", PAYLOAD_B9, "0"),
196	        ("B9/4", PAYLOAD_B9, "4"),
197	        ("B9/8", PAYLOAD_B9, "8"),
198	        ("MIXED/8", PAYLOAD_MIXED, "8"),
199	        ("ONE_LF/0", PAYLOAD_ONE_LF, "0"),
