224	    // B9 holds b"alpha" at both position 0 and position 4.
225	    let tmp = TempFile::create(PAYLOAD_B9);
226	    let p0 = String::from_utf8(run_prove(&tmp.path, "0").stdout).unwrap();
227	    let p4 = String::from_utf8(run_prove(&tmp.path, "4").stdout).unwrap();
228	    assert_ne!(p0, p4, "proofs for positions 0 and 4 must differ despite equal bytes");
229	    assert!(p0.contains("\"leaf_index\":0"));
230	    assert!(p4.contains("\"leaf_index\":4"));
