232	    assert_eq!(root_field(p0.trim_end()), ROOT_B9);
233	    assert_eq!(root_field(p4.trim_end()), ROOT_B9);
234	    // The B8 batch also contains "alpha" at position 0 but is a different
235	    // batch, so its m=0 proof is not interchangeable with B9 m=0.
236	    let tmp8 = TempFile::create(PAYLOAD_B8);
237	    let p0_b8 = String::from_utf8(run_prove(&tmp8.path, "0").stdout).unwrap();
