242	fn trailing_lf_equivalence_holds_for_proofs() {
243	    // The trailing/no-trailing-LF forms name the same record sequence, so
244	    // proofs must be byte-identical (not just equally rooted).
245	    for (records, index) in [(B9_RECORDS, "4"), (B9_RECORDS, "8")] {
