    let out = Command::new(common::bin()).arg("root").arg(&dir.path).output().unwrap();
    assert_eq!(out.status.code(), Some(1), "directory path should exit 1");
    assert!(out.stdout.is_empty());
    assert!(!out.stderr.is_empty());
}

