use std::env;
use std::ffi::OsStr;
use std::fs;
use std::path::Path;
use std::process::ExitCode;

const VERSION: &str = "0.1.0";

const USAGE: &str = "\
Usage:
    roottrace root <file>
    roottrace prove <file> <record-index>
    roottrace --version

Commands:
    root <file>
        Print the SHA-256 RFC 6962 Merkle Tree Hash of all records in <file>
        as one line of 64 lowercase hexadecimal characters.

    prove <file> <record-index>
        Print the RFC 6962 section 2.1.1 inclusion (membership) proof for the
        record at <record-index> within the whole batch. The index is
        0-based and counts records in file order: 0 is the first record,
        1 the second, and so on; the same content at multiple positions gets
        the proof for the exact position given, with no deduplication. Output
        is one JSON object with the fields tree_size, leaf_index, root and
        audit_path (leaf-to-root hashes, lowercase hex; empty for a batch of
        exactly one record).

        Example:
            roottrace prove batch.txt 0

Exit status:
    0  success
    1  the file cannot be read, or the record index does not exist
    2  usage error (unknown command, missing or extra arguments, bad index)";

fn main() -> ExitCode {
    // File paths travel as OsString, never as String: on Unix a filename may
    // contain arbitrary bytes (e.g. 0xff) that are not valid UTF-8, and such
    // a path must still reach fs::read byte for byte. Only the command name
    // and the record index are required to be UTF-8/ASCII text.
    let args: Vec<std::ffi::OsString> = env::args_os().skip(1).collect();
    match args.as_slice() {
        [flag] if flag == "--version" => {
            println!("roottrace {VERSION}");
            ExitCode::SUCCESS
        }
        [cmd, path] if cmd == "root" => match merkle_root_of_file(path) {
            Ok(root) => {
                println!("{}", hex(&root));
                ExitCode::SUCCESS
            }
            Err(reason) => {
                eprintln!("roottrace: {reason}");
                ExitCode::FAILURE
            }
        },
        [cmd, path, index] if cmd == "prove" => match parse_index_os(index) {
            Some(index) => match proof_for_file(path, index) {
                Ok(proof) => {
                    println!("{}", proof);
                    ExitCode::SUCCESS
                }
                Err(ProveError::Read(reason)) => {
                    eprintln!("roottrace: {reason}");
                    ExitCode::FAILURE
                }
                Err(ProveError::Missing(index, size)) => {
                    if size == 0 {
                        eprintln!(
                            "roottrace: record index {index} does not exist: the file holds zero records"
                        );
                    } else {
                        eprintln!(
                            "roottrace: record index {index} does not exist: file holds {size} record(s), valid indices are 0 through {}",
                            size - 1
                        );
                    }
                    ExitCode::FAILURE
                }
            },
            None => {
                eprintln!(
                    "roottrace: invalid record index '{}': expected a decimal non-negative integer of ASCII digits",
                    index.to_string_lossy()
                );
                eprintln!("{USAGE}");
                ExitCode::from(2)
            }
        },
        _ => {
            eprintln!("{USAGE}");
            ExitCode::from(2)
        }
    }
}

enum ProveError {
    Read(String),
    Missing(u64, u64),
}

fn merkle_root_of_file(path: &OsStr) -> Result<[u8; 32], String> {
    let data = fs::read(Path::new(path)).map_err(|e| read_error(path, e))?;
    Ok(mth(&split_records(&data)))
}

fn proof_for_file(path: &OsStr, index: u64) -> Result<String, ProveError> {
    let data = fs::read(Path::new(path)).map_err(|e| ProveError::Read(read_error(path, e)))?;
    let records = split_records(&data);
    let size = records.len() as u64;
    if index >= size {
        return Err(ProveError::Missing(index, size));
    }
    let idx = index as usize;
    let (root, audit_path) = root_and_path(&records, idx);
    Ok(proof_json(size, index, &root, &audit_path))
}

/// Describe a failed file read. The path is rendered with the replacement
/// character for bytes that are not valid UTF-8, so a failure stays a stable
/// exit-1 error even when the path itself cannot be displayed.
fn read_error(path: &OsStr, e: std::io::Error) -> String {
    format!("cannot read '{}': {e}", path.to_string_lossy())
}

/// Parse a record index given as an OS argument: one or more ASCII decimal
/// digits, non-negative, no sign or whitespace, fitting in an unsigned 64-bit
/// integer. A non-UTF-8 argument fails the ASCII-digit check just like any
/// other non-digit text, which is a usage error rather than a read error.
fn parse_index_os(arg: &OsStr) -> Option<u64> {
    let bytes = arg.as_encoded_bytes();
    if bytes.is_empty() || !bytes.iter().all(|b| b.is_ascii_digit()) {
        return None;
    }
    let mut value: u64 = 0;
    for &b in bytes {
        value = value.checked_mul(10)?.checked_add(u64::from(b - b'0'))?;
    }

